class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 1_000_000_007
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - ord('a')] += 1

        for _ in range(t):
            next_cnt = [0] * 26
            for i in range(25):
                next_cnt[i + 1] = cnt[i]
            z = cnt[25]
            next_cnt[0] = (next_cnt[0] + z) % MOD
            next_cnt[1] = (next_cnt[1] + z) % MOD
            cnt = next_cnt

        return sum(cnt) % MOD

class Solution {
public:
    int lengthAfterTransformations(string s, int t) {
        const int MOD = 1000000007;
        vector<long long> cnt(26, 0);
        for (char ch : s) cnt[ch - 'a']++;

        for (int step = 0; step < t; ++step) {
            vector<long long> next_cnt(26, 0);
            for (int i = 0; i < 25; ++i) {
                next_cnt[i + 1] = cnt[i];
            }
            long long z = cnt[25];
            next_cnt[0] = (next_cnt[0] + z) % MOD;
            next_cnt[1] = (next_cnt[1] + z) % MOD;
            cnt = std::move(next_cnt);
        }

        long long ans = 0;
        for (long long v : cnt) ans = (ans + v) % MOD;
        return ans;
    }
};

class Solution {
    public int lengthAfterTransformations(String s, int t) {
        long MOD = 1_000_000_007;
        long[] cnt = new long[26];
        for (int i = 0; i < s.length(); i++) {
            cnt[s.charAt(i) - 'a']++;
        }

        for (int step = 0; step < t; step++) {
            long[] nextCnt = new long[26];
            for (int i = 0; i < 25; i++) {
                nextCnt[i + 1] = cnt[i];
            }
            long z = cnt[25];
            nextCnt[0] = (nextCnt[0] + z) % MOD;
            nextCnt[1] = (nextCnt[1] + z) % MOD;
            cnt = nextCnt;
        }

        long ans = 0;
        for (long v : cnt) ans = (ans + v) % MOD;
        return (int) ans;
    }
}

